9: import { persist } from "zustand/middleware";
10: import type { Esporte } from "@/lib/quadras";
11: 
12: // ─── Tipos ────────────────────────────────────────────────────────────────────
13: 
14: export type StatusReserva =
15:   | "em_processamento" // lock temporário durante o checkout
16:   | "pendente"         // sinal pago, restante a pagar no dia
17:   | "confirmada"       // pagamento do sinal confirmado
18:   | "cancelada";       // reserva cancelada
19: 
20: export type StatusWhatsApp = "nao_enviado" | "enviado" | "falhou";
21: 
22: export interface Reserva {
23:   id: string;
24:   quadraId: string;
25: 
26:   // Identificação do cliente
27:   nomeCliente: string;
28:   whatsappCliente: string;
29:   cpfCliente: string;
30: 
31:   // Agendamento
32:   data: string;        // "YYYY-MM-DD"
33:   horarios: string[];  // ex: ["13:00", "14:00", "15:00"]
34:   horaInicio: string;  // primeiro slot
35:   horaFim: string;     // última hora + 1h (ex: "16:00")
36: 
37:   // Financeiro
38:   valorTotal: number;
39:   valorSinal: number;    // 40% do total
40:   valorPendente: number; // 60% do total
41: 
42:   // Estado
43:   status: StatusReserva;
44:   statusWhatsApp: StatusWhatsApp;
45:   criadaEm: string; // ISO datetime
46: 
47:   // Opcionais
48:   esporte?: Esporte;
49:   observacoes?: string;
50: }
51: 
52: // ─── State & Actions ──────────────────────────────────────────────────────────
53: 
54: interface ReservasState {
55:   reservas: Reserva[];
56:   isLoadedFromDb: boolean;
57: 
58:   // Mutations
59:   setReservas: (reservas: Reserva[]) => void;
60:   adicionarReserva: (reserva: Reserva) => void;
61:   atualizarReserva: (id: string, dados: Partial<Reserva>) => void;
62:   removerReserva: (id: string) => void;
63: 
64:   // Computed helpers (usados pelo service)
65:   getReservaById: (id: string) => Reserva | undefined;
66:   getReservasPorData: (data: string) => Reserva[];
67: }
68: 
69: // ─── Store ────────────────────────────────────────────────────────────────────
70: 
71: export const useReservasStore = create<ReservasState>()(
