83:           if (existe) {
84:             return {
85:               reservas: state.reservas.map((r) =>
86:                 r.id === reserva.id ? reserva : r
87:               ),
88:             };
89:           }
90:           return { reservas: [reserva, ...state.reservas] };
91:         }),
92: 
93:       atualizarReserva: (id, dados) =>
94:         set((state) => ({
95:           reservas: state.reservas.map((r) =>
96:             r.id === id ? { ...r, ...dados } : r
97:           ),
98:         })),
99: 
100:       removerReserva: (id) =>
101:         set((state) => ({
102:           reservas: state.reservas.filter((r) => r.id !== id),
