62:   useEffect(() => {
63:     let isMounted = true;
64: 
65:     // Busca dados do Supabase na inicialização
66:     if (isSupabaseConfigured() && !isLoadedFromDb) {
67:       fetchReservasSupabase().then((dados) => {
68:         if (isMounted && dados) {
69:           setReservas(dados);
70:         }
71:       });
72:     }
73: 
74:     // Configura canal Realtime compartilhado
75:     realtimeListenersCount++;
76:     if (realtimeListenersCount === 1 && isSupabaseConfigured()) {
77:       activeRealtimeCleanup = subscreverReservasSupabase(
78:         (nova) => {
79:           useReservasStore.getState().adicionarReserva(nova);
80:         },
81:         (atualizada) => {
