import { supabase, isSupabaseConfigured } from "./client";
import { normalizarTelefoneE164 } from "@/lib/constants";
import type { UserProfile } from "./types";

const STORAGE_MOCK_USER_KEY = "reservei_mock_current_user";
const STORAGE_MOCK_USERS_DB = "reservei_mock_users_db";

interface MockStoredUser {
  id: string;
  nome: string;
  telefone: string;
  dataNascimento?: string | null;
  password?: string;
  criadoEm: string;
}

function getMockUsers(): MockStoredUser[] {
  try {
    const raw = localStorage.getItem(STORAGE_MOCK_USERS_DB);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveMockUsers(users: MockStoredUser[]) {
  try {
    localStorage.setItem(STORAGE_MOCK_USERS_DB, JSON.stringify(users));
  } catch (err) {
    console.error("Erro ao salvar mock users", err);
  }
}

/**
 * Cria cadastro de usuário com Telefone e Senha (Phone Auth)
 */
export async function cadastrarUsuarioSupabase(
  nome: string,
  telefone: string,
  senha: string,
  dataNascimento?: string
): Promise<{ user: UserProfile | null; error?: string }> {
  const telefoneE164 = normalizarTelefoneE164(telefone);

  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.auth.signUp({
        phone: telefoneE164,
        password: senha,
        options: {
          data: {
            nome,
            telefone,
            data_nascimento: dataNascimento || null,
          },
        },
      });

      if (error) {
        // Se a mensagem for sobre confirmação de telefone, explicamos amigavelmente
        return { user: null, error: error.message };
      }

      if (data.user) {
        const perfil: UserProfile = {
          id: data.user.id,
          nome,
          telefone,
          dataNascimento: dataNascimento || null,
          criadoEm: data.user.created_at,
        };

        // Salva perfil na tabela public.profiles
        try {
          await supabase.from("profiles").upsert([
            {
              id: perfil.id,
              nome: perfil.nome,
              telefone: perfil.telefone,
              data_nascimento: perfil.dataNascimento,
            },
          ]);
        } catch (profileErr) {
          console.warn("[Auth] Não foi possível salvar em profiles:", profileErr);
        }

        return { user: perfil };
      }
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : "Erro desconhecido ao cadastrar";
      console.error("[Supabase Auth] Erro inesperado:", errMsg);
      // Fallback para mock abaixo se falhar conexão
    }
  }

  // Fallback LocalStorage (modo offline / mock)
  const users = getMockUsers();
  const existe = users.find((u) => u.telefone.replace(/\D/g, "") === telefone.replace(/\D/g, ""));
  if (existe) {
    return { user: null, error: "Este número de telefone já possui uma conta cadastrada." };
  }

  const novoMock: MockStoredUser = {
    id: `usr_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    nome,
    telefone,
    dataNascimento: dataNascimento || null,
    password: senha,
    criadoEm: new Date().toISOString(),
  };

  users.push(novoMock);
  saveMockUsers(users);

  const perfil: UserProfile = {
    id: novoMock.id,
    nome: novoMock.nome,
    telefone: novoMock.telefone,
    dataNascimento: novoMock.dataNascimento,
    criadoEm: novoMock.criadoEm,
  };

  try {
    localStorage.setItem(STORAGE_MOCK_USER_KEY, JSON.stringify(perfil));
  } catch {}

  return { user: perfil };
}

/**
 * Realiza login com Telefone e Senha
 */
export async function loginUsuarioSupabase(
  telefone: string,
  senha: string
): Promise<{ user: UserProfile | null; error?: string }> {
  const telefoneE164 = normalizarTelefoneE164(telefone);

  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        phone: telefoneE164,
        password: senha,
      });

      if (error) {
        return { user: null, error: error.message };
      }

      if (data.user) {
        // Tenta buscar da tabela profiles
        let perfil: UserProfile | null = null;
        try {
          const { data: profileRow } = await supabase
            .from("profiles")
            .select("*")
            .eq("id", data.user.id)
            .single();

          if (profileRow) {
            perfil = {
              id: profileRow.id,
              nome: profileRow.nome || (data.user.user_metadata?.nome as string) || "Cliente",
              telefone: profileRow.telefone || telefone,
              dataNascimento: profileRow.data_nascimento,
              criadoEm: profileRow.criado_em || data.user.created_at,
            };
          }
        } catch {
          // ignora erro e usa metadados
        }

        if (!perfil) {
          perfil = {
            id: data.user.id,
            nome: (data.user.user_metadata?.nome as string) || "Cliente",
            telefone: (data.user.user_metadata?.telefone as string) || telefone,
            dataNascimento: (data.user.user_metadata?.data_nascimento as string) || null,
            criadoEm: data.user.created_at,
          };
        }

        return { user: perfil };
      }
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : "Erro inesperado ao conectar";
      console.error("[Supabase Auth] Erro ao logar:", errMsg);
    }
  }

  // Fallback LocalStorage
  const users = getMockUsers();
  const digits = telefone.replace(/\D/g, "");
  const encontrado = users.find(
    (u) => u.telefone.replace(/\D/g, "") === digits && u.password === senha
  );

  if (!encontrado) {
    return { user: null, error: "Telefone ou senha incorretos." };
  }

  const perfil: UserProfile = {
    id: encontrado.id,
    nome: encontrado.nome,
    telefone: encontrado.telefone,
    dataNascimento: encontrado.dataNascimento,
    criadoEm: encontrado.criadoEm,
  };

  try {
    localStorage.setItem(STORAGE_MOCK_USER_KEY, JSON.stringify(perfil));
  } catch {}

  return { user: perfil };
}

/**
 * Obtém usuário logado atualmente (ou null)
 */
export async function obterUsuarioAtual(): Promise<UserProfile | null> {
  if (isSupabaseConfigured()) {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        // Tenta obter perfil
        const { data: profileRow } = await supabase
          .from("profiles")
          .select("*")
          .eq("id", session.user.id)
          .single();

        if (profileRow) {
          return {
            id: profileRow.id,
            nome: profileRow.nome || (session.user.user_metadata?.nome as string) || "Cliente",
            telefone: profileRow.telefone || (session.user.user_metadata?.telefone as string) || "",
            dataNascimento: profileRow.data_nascimento,
            criadoEm: profileRow.criado_em || session.user.created_at,
          };
        }

        return {
          id: session.user.id,
          nome: (session.user.user_metadata?.nome as string) || "Cliente",
          telefone: (session.user.user_metadata?.telefone as string) || "",
          dataNascimento: (session.user.user_metadata?.data_nascimento as string) || null,
          criadoEm: session.user.created_at,
        };
      }
    } catch (err) {
      console.warn("[Auth] Não foi possível restaurar sessão Supabase:", err);
    }
  }

  // Fallback LocalStorage
  try {
    const raw = localStorage.getItem(STORAGE_MOCK_USER_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

/**
 * Desconecta o usuário
 */
export async function logoutUsuarioSupabase(): Promise<void> {
  if (isSupabaseConfigured()) {
    try {
      await supabase.auth.signOut();
    } catch (err) {
      console.warn("[Auth] Erro no logout:", err);
    }
  }

  try {
    localStorage.removeItem(STORAGE_MOCK_USER_KEY);
  } catch {}
}

/**
 * Atualiza os dados de perfil do usuário
 */
export async function atualizarPerfilSupabase(
  userId: string,
  dados: Partial<Omit<UserProfile, "id" | "criadoEm">>
): Promise<UserProfile | null> {
  if (isSupabaseConfigured()) {
    try {
      await supabase
        .from("profiles")
        .update({
          nome: dados.nome,
          telefone: dados.telefone,
          data_nascimento: dados.dataNascimento,
        })
        .eq("id", userId);

      await supabase.auth.updateUser({
        data: {
          nome: dados.nome,
          telefone: dados.telefone,
          data_nascimento: dados.dataNascimento,
        },
      });
    } catch (err) {
      console.warn("[Auth] Erro ao atualizar perfil:", err);
    }
  }

  // Fallback e sincronização local
  try {
    const raw = localStorage.getItem(STORAGE_MOCK_USER_KEY);
    if (raw) {
      const current = JSON.parse(raw);
      const updated = { ...current, ...dados };
      localStorage.setItem(STORAGE_MOCK_USER_KEY, JSON.stringify(updated));
      return updated;
    }
  } catch {}

  return null;
}

/**
 * Exclui a conta do usuário (Direito de esquecimento / LGPD)
 */
export async function excluirContaSupabase(userId: string): Promise<boolean> {
  if (isSupabaseConfigured()) {
    try {
      // Deleta perfil associado
      await supabase.from("profiles").delete().eq("id", userId);
      // Desconecta sessão
      await supabase.auth.signOut();
    } catch (err) {
      console.warn("[Auth] Erro ao excluir perfil:", err);
    }
  }

  try {
    localStorage.removeItem(STORAGE_MOCK_USER_KEY);
    const users = getMockUsers().filter((u) => u.id !== userId);
    saveMockUsers(users);
  } catch {}

  return true;
}

"use client";

import { useState, useEffect, useCallback } from "react";
import type { UserProfile } from "@/lib/supabase/types";
import {
  cadastrarUsuarioSupabase,
  loginUsuarioSupabase,
  obterUsuarioAtual,
  logoutUsuarioSupabase,
  atualizarPerfilSupabase,
  excluirContaSupabase,
} from "@/lib/supabase/authService";
import { supabase, isSupabaseConfigured } from "@/lib/supabase/client";

export function useUserAuth() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  // Carrega usuário atual na inicialização
  useEffect(() => {
    let isMounted = true;

    async function carregarSessao() {
      try {
        const u = await obterUsuarioAtual();
        if (isMounted) {
          setUser(u);
          setLoading(false);
        }
      } catch {
        if (isMounted) setLoading(false);
      }
    }

    void carregarSessao();

    // Inscrição para mudanças de autenticação no Supabase
    if (isSupabaseConfigured()) {
      const {
        data: { subscription },
      } = supabase.auth.onAuthStateChange(async (_event, session) => {
        if (!isMounted) return;
        if (session?.user) {
          const u = await obterUsuarioAtual();
          if (isMounted) setUser(u);
        } else {
          // Só limpa se não estiver no fallback local
          const u = await obterUsuarioAtual();
          if (isMounted) setUser(u);
        }
      });

      return () => {
        isMounted = false;
        subscription.unsubscribe();
      };
    }

    return () => {
      isMounted = false;
    };
  }, []);

  const login = useCallback(
    async (telefone: string, senha: string): Promise<{ success: boolean; error?: string }> => {
      setLoading(true);
      const res = await loginUsuarioSupabase(telefone, senha);
      setLoading(false);
      if (res.user) {
        setUser(res.user);
        return { success: true };
      }
      return { success: false, error: res.error || "Erro ao realizar login." };
    },
    []
  );

  const cadastrar = useCallback(
    async (
      nome: string,
      telefone: string,
      senha: string,
      dataNascimento?: string
    ): Promise<{ success: boolean; user?: UserProfile; error?: string }> => {
      setLoading(true);
      const res = await cadastrarUsuarioSupabase(nome, telefone, senha, dataNascimento);
      setLoading(false);
      if (res.user) {
        setUser(res.user);
        return { success: true, user: res.user };
      }
      return { success: false, error: res.error || "Erro ao cadastrar usuário." };
    },
    []
  );

  const logout = useCallback(async () => {
    setLoading(true);
    await logoutUsuarioSupabase();
    setUser(null);
    setLoading(false);
  }, []);

  const atualizarPerfil = useCallback(
    async (dados: Partial<Omit<UserProfile, "id" | "criadoEm">>): Promise<boolean> => {
      if (!user) return false;
      const updated = await atualizarPerfilSupabase(user.id, dados);
      if (updated) {
        setUser(updated);
        return true;
      }
      return false;
    },
    [user]
  );

  const excluirConta = useCallback(async (): Promise<boolean> => {
    if (!user) return false;
    const ok = await excluirContaSupabase(user.id);
    if (ok) {
      setUser(null);
      return true;
    }
    return false;
  }, [user]);

  return {
    user,
    loading,
    isAutenticado: Boolean(user),
    login,
    cadastrar,
    logout,
    atualizarPerfil,
    excluirConta,
  };
}

