  formatarDataExibicao,
  formatarMoeda,
  mascaraWhatsApp,
  getHoje,
  TELEFONE_COMPLEXO,
  NOME_COMPLEXO,
} from "@/lib/constants";
import { QUADRAS } from "@/lib/quadras";
