const { createClient } = require("@supabase/supabase-js");

const supabaseUrl = "https://wjtckujicvryvifbamug.supabase.co";
const supabaseAnonKey = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6IndqdGNrdWppY3ZyeXZpZmJhbXVnIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTA4MTQ1MjEsImV4cCI6MjEwNjM5MDUyMX0.jbuAoRXoVwZpAeGGUlaIV2bK3EPdfk4I1o7axDxfJ68";

const supabase = createClient(supabaseUrl, supabaseAnonKey);

async function cadastrar(nome, telefone, senha, dataNascimento) {
  const digits = telefone.replace(/\D/g, "");

  // 1. Tenta salvar na tabela 'usuarios' do Supabase
  const id = `usr_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
